-- Fantasy Club — PostgreSQL/Supabase schema foundation
create extension if not exists pgcrypto;
create type public.member_role as enum ('admin','participant');
create type public.round_status as enum ('draft','open','closed','cancelled','reopened');
create type public.stats_method as enum ('manual','events');
create table public.leagues(id uuid primary key default gen_random_uuid(),name text not null,invite_code text not null unique default upper(substr(encode(gen_random_bytes(8),'hex'),1,10)),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.league_members(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,user_id uuid not null references auth.users on delete restrict,display_name text not null,role public.member_role not null default 'participant',active boolean not null default true,created_at timestamptz not null default now(),unique(league_id,user_id));
create table public.players(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,name text not null,team text not null default '',role text not null default '',active boolean not null default true,created_at timestamptz not null default now(),unique(league_id,name));
create table public.rounds(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,number int not null check(number>0),status public.round_status not null default 'draft',opened_at timestamptz,closed_at timestamptz,cancelled_at timestamptz,stats_confirmed boolean not null default false,reason text not null,created_by uuid references auth.users(id),unique(league_id,number));
create table public.round_availability(round_id uuid not null references public.rounds on delete cascade,player_id uuid not null references public.players on delete cascade,available boolean not null,reason text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),primary key(round_id,player_id));
create table public.player_stats(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,round_id uuid not null references public.rounds on delete cascade,player_id uuid not null references public.players on delete cascade,method public.stats_method not null,goals int not null default 0 check(goals>=0),assists int not null default 0 check(assists>=0),wins int not null default 0 check(wins>=0),draws int not null default 0 check(draws>=0),losses int not null default 0 check(losses>=0),confirmed boolean not null default false,source_label text,reason text not null,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(round_id,player_id));
create table public.stat_events(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,round_id uuid not null references public.rounds on delete cascade,player_id uuid not null references public.players on delete cascade,event_type text not null check(event_type in ('goal','assist','win','draw','loss')),quantity int not null default 1 check(quantity>0),source_label text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.fantasy_picks(round_id uuid not null references public.rounds on delete cascade,user_id uuid not null references auth.users on delete cascade,player_id uuid not null references public.players on delete restrict,created_at timestamptz not null default now(),primary key(round_id,user_id,player_id));
create table public.mvp_votes(round_id uuid not null references public.rounds on delete cascade,voter_id uuid not null references auth.users on delete cascade,player_id uuid not null references public.players on delete restrict,rank int not null check(rank between 1 and 3),created_at timestamptz not null default now(),primary key(round_id,voter_id,rank),unique(round_id,voter_id,player_id));
create table public.mvp_results(round_id uuid not null references public.rounds on delete cascade,player_id uuid not null references public.players on delete cascade,vote_points int not null default 0,first_place_votes int not null default 0,base_points numeric(10,2) not null default 0,is_winner boolean not null default false,final_points numeric(10,2) not null default 0,primary key(round_id,player_id));
create table public.player_round_results(round_id uuid not null references public.rounds on delete cascade,player_id uuid not null references public.players on delete cascade,base_points numeric(10,2) not null,final_points numeric(10,2) not null,primary key(round_id,player_id));
create table public.fantasy_round_results(round_id uuid not null references public.rounds on delete cascade,user_id uuid not null references auth.users on delete cascade,points numeric(10,2) not null,selected_mvp_winner boolean not null default false,valid_selection boolean not null default false,primary key(round_id,user_id));
create table public.audit_log(id bigint generated always as identity primary key,league_id uuid not null references public.leagues on delete cascade,actor_id uuid references auth.users(id),action text not null,reason text not null,old_values jsonb,new_values jsonb,created_at timestamptz not null default now());
create index on public.rounds(league_id,number);create index on public.player_stats(round_id,player_id);create index on public.fantasy_round_results(user_id,round_id);create index on public.audit_log(league_id,created_at desc);
create or replace function public.is_member(p_league uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.league_members m where m.league_id=p_league and m.user_id=auth.uid() and m.active) $$;
create or replace function public.is_admin(p_league uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.league_members m where m.league_id=p_league and m.user_id=auth.uid() and m.active and m.role='admin') $$;
alter table public.leagues enable row level security;alter table public.league_members enable row level security;alter table public.players enable row level security;alter table public.rounds enable row level security;alter table public.round_availability enable row level security;alter table public.player_stats enable row level security;alter table public.stat_events enable row level security;alter table public.fantasy_picks enable row level security;alter table public.mvp_votes enable row level security;alter table public.mvp_results enable row level security;alter table public.player_round_results enable row level security;alter table public.fantasy_round_results enable row level security;alter table public.audit_log enable row level security;
create policy "league members read league" on public.leagues for select using(public.is_member(id));
create policy "members read membership" on public.league_members for select using(public.is_member(league_id));
create policy "members read players" on public.players for select using(public.is_member(league_id));
create policy "admins manage players" on public.players for all using(public.is_admin(league_id)) with check(public.is_admin(league_id));
create policy "members read rounds" on public.rounds for select using(public.is_member(league_id));
create policy "admins manage rounds" on public.rounds for all using(public.is_admin(league_id)) with check(public.is_admin(league_id));
create policy "members read availability" on public.round_availability for select using(exists(select 1 from public.rounds r where r.id=round_id and public.is_member(r.league_id)));
create policy "admins manage availability" on public.round_availability for all using(exists(select 1 from public.rounds r where r.id=round_id and public.is_admin(r.league_id))) with check(exists(select 1 from public.rounds r where r.id=round_id and public.is_admin(r.league_id)));
create policy "members read stats" on public.player_stats for select using(public.is_member(league_id));
create policy "admins manage stats" on public.player_stats for all using(public.is_admin(league_id)) with check(public.is_admin(league_id));
create policy "admins manage events" on public.stat_events for all using(public.is_admin(league_id)) with check(public.is_admin(league_id));
-- Votes and picks deliberately have no direct SELECT policy for participants: use secure RPCs/views that only expose a user's own pre-close submission and reveal aggregate data after closure.
create policy "users manage own picks through RLS" on public.fantasy_picks for select using(user_id=auth.uid() and exists(select 1 from public.rounds r where r.id=round_id and public.is_member(r.league_id) and r.status in ('open','reopened')) or exists(select 1 from public.rounds r where r.id=round_id and public.is_member(r.league_id) and r.status='closed'));
create policy "admins read audit" on public.audit_log for select using(public.is_admin(league_id));
create policy "members read player totals" on public.player_round_results for select using(exists(select 1 from public.rounds r where r.id=round_id and public.is_member(r.league_id) and r.status='closed'));
create policy "members read fantasy totals" on public.fantasy_round_results for select using(exists(select 1 from public.rounds r where r.id=round_id and public.is_member(r.league_id) and r.status='closed'));
create policy "members read MVP after close" on public.mvp_results for select using(exists(select 1 from public.rounds r where r.id=round_id and public.is_member(r.league_id) and r.status='closed'));
